import math

def get_prime_power(n):
    if n <= 0:
        return None, 0
    for p in range(2, int(math.sqrt(n)) + 1):
        if n % p == 0:
            count = 0
            while n % p == 0:
                n //= p
                count += 1
            if n == 1:
                return p, count
            else:
                # If composite, and factor remains, it's not a prime power
                return None, 0
    if n > 1:
        return n, 1 # n is prime
    return None, 0

def check_solution(m, n):
    a_val = m**2 + n
    b_val = m + n**2

    p_a, A = get_prime_power(a_val)
    p_b, B = get_prime_power(b_val)

    if p_a is not None and p_b is not None and p_a == p_b:
        if A > 1 and B > 1:
            return True, p_a, A, B
    return False, None, None, None

