import math

def is_power(k, p):
    if k <= 0:
        return False
    if k == 1:
        # Assuming A > 1 constraint means 1 is not allowed.
        return False

    # Check if k is a power of p
    if k % p != 0:
        return False

    val = k
    while val > 1:
        if val % p != 0:
            return False
        val //= p
    return True

def solve():
    solutions = []
    primes = [5, 7, 11]
    N_max = 10

    for p in primes:
        for m in range(1, N_max + 1):
            for n in range(1, N_max + 1):
                M2_n = m*m + n
                M_n2 = m + n*n

                # Check if M2_n and M_n2 are powers of p, and exponents > 1
                if is_power(M2_n, p) and is_power(M_n2, p):
                    # Calculate exponents (A and B) to ensure A>1 and B>1
                    A = round(math.log(M2_n, p))
                    B = round(math.log(M_n2, p))

                    # Double check conditions (A>1 and B>1)
                    if A > 1 and B > 1:
                        solutions.append(((m, n, p), m + n + p))

    return solutions

results = solve()
